<?php $canMaintain=Auth::isAdmin()||in_array($module,['pc','perangkat','software'],true); ?><div class="toolbar"><form class="search"><svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="8"/><path d="M21 21l-4.3-4.3"/></svg><input name="q" value="<?=e($q)?>" placeholder="Cari data..."></form><?php if($canMaintain):?><a class="btn primary" href="/<?=$module?>/create">+ Tambah data</a><?php endif;?></div>
<div class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Identitas</th><?php if($module==='pc'):?><th>Lokasi</th><th>Status</th><?php elseif($module==='perangkat'):?><th>Kategori</th><th>Jumlah</th><th>Lokasi</th><th>Status</th><?php elseif($module==='software'):?><th>Versi</th><th>Kategori</th><th>Status</th><?php elseif($module==='tugas'):?><th>Prioritas</th><th>PIC</th><th>Status</th><?php elseif($module==='pemeriksaan'):?><th>Tanggal</th><th>Kondisi</th><th>Unit terdampak</th><?php else:?><th>Tanggal</th><th>Lokasi</th><th>Status</th><?php endif;?><th class="actions">Aksi</th></tr></thead><tbody>
<?php foreach($rows as $r):?><tr><td><strong><?=e($r['title']??$r['name']??('Pemeriksaan #'.$r['id']))?></strong><small><?=e($r['number']??$r['code']??$r['findings']??'')?></small></td><?php if($module==='pc'):?><td><?=e($r['location']??'-')?></td><td><span class="badge"><?=e($r['status'])?></span></td><?php elseif($module==='perangkat'):?><td><?=e($r['category']??'-')?></td><td><?=e($r['quantity'])?></td><td><?=e($r['location']??'-')?></td><td><span class="badge"><?=e($r['status'])?></span></td><?php elseif($module==='software'):?><td><?=e($r['version']??'-')?></td><td><?=e($r['category']??'-')?></td><td><span class="badge"><?=e($r['status'])?></span></td><?php elseif($module==='tugas'):?><td><?=e($r['priority'])?></td><td><?=e($r['assignee']??'Belum ada')?></td><td><span class="badge"><?=e($r['status'])?></span></td><?php elseif($module==='pemeriksaan'):?><td><?=e($r['inspected_at'])?></td><td><?=e($r['condition_after']??'-')?></td><td><?=e($r['affected_count'])?></td><?php else:?><td><?=e($r['event_date'])?></td><td><?=e($r['location_id']??'-')?></td><td><span class="badge"><?=e($r['status'])?></span></td><?php endif;?><td class="actions"><?php if($module==='tugas'&&$r['status']==='Tersedia'&&!$r['assignee_id']):?><form method="post" action="/tugas/ambil/<?=$r['id']?>"><?=Csrf::field()?><button class="link-btn">Ambil</button></form><?php endif;if($canMaintain):?><a class="icon-action" href="/<?=$module?>/edit/<?=$r['id']?>" aria-label="Ubah">✎</a><?php endif;if(Auth::isAdmin()):?><form method="post" action="/<?=$module?>/delete/<?=$r['id']?>" onsubmit="return confirm('Hapus data ini?')"><?=Csrf::field()?><button class="icon-action danger" aria-label="Hapus">×</button></form><?php endif;?></td></tr><?php endforeach;?>
<?php if(!$rows):?><tr><td colspan="8"><div class="empty">Belum ada data yang sesuai.</div></td></tr><?php endif;?></tbody></table></div></div>
<?php if($module==='tugas'&&$rows):?><div class="result-links"><?php foreach($rows as $task):?><a class="btn ghost" href="/tugas/hasil/<?=$task['id']?>"><?=__('Hasil','Result')?> · <?=e($task['number'])?></a><?php endforeach;?></div><?php endif;?>

